var n=`1251-festival-dumplings`;var a=`world-1251`;var t=`JM`;var r=`central-america-caribbean`;var o=8;var s=42;var g={en:`Festival Dumplings`,ua:`Смажені кнедлики фестиваль`};var l={en:`Festival Dumplings is a dish from Jamaica featuring all-purpose flour, cornmeal, baking powder. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Смажені кнедлики фестиваль, страва кухні країни Ямайка з такими основними складниками: пшеничне борошно універсальне, кукурудзяна крупа дрібного помелу, розпушувач тіста. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var d=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 15 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 15 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:15,i:[[`all-purpose-flour`,420,`g`],[`cornmeal`,110,`g`],[`white-granulated-sugar`,90,`g`],[`baking-powder`,14,`g`],[`table-salt`,5,`g`],[`water`,280,`ml`]]},{en:`Divide and shape the prepared mixture or dough into even portions and arrange on a lined baking sheet or appropriate molds, leaving enough room for expansion.`,ua:`Розділіть і сформуйте підготовлене тісто чи масу на однакові порції, викладіть на деко з пергаментом або у форми, залишивши місце для збільшення об’єму.`,t:[`pre-shaping-dough`,`final-proofing`],m:11,i:[]},{en:`Fry shaped portions in small batches in oil heated to about 170–175°C for about 13 minutes, until golden; drain on a rack.`,ua:`Смажте сформовані вироби невеликими партіями в олії температурою приблизно 170–175°C близько 13 хвилин до золотистості; викладіть на решітку.`,t:[`deep-frying`],m:13,i:[[`canola-oil`,800,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`ground-cinnamon`,4,`g`]]}];var u={slug:n,id:a,country:`JM`,region:r,servings:8,minutes:42,title:g,text:l,steps:d};export{t as country,u as default,a as id,s as minutes,r as region,o as servings,n as slug,d as steps,l as text,g as title};